#include "hddvd.h"
#include <stdio.h>
#include <stdlib.h>
static int show_object(void*o,const hddvd_aca_entry*e){const char*aca=o;void*b=NULL;size_t n=0;hddvd_object*object=NULL;int rc=hddvd_aca_read_member(aca,e->name,&b,&n);if(rc)return rc;rc=hddvd_object_parse(b,n,&object);free(b);if(rc)return rc;printf("Object: %s type=0x%02x flags=0x%06x payload=%zu trailer=%zu protected=%s",e->name,hddvd_object_type(object),hddvd_object_flags(object),hddvd_object_payload_size(object),hddvd_object_trailer_size(object),hddvd_object_is_protected(object)?"yes":"no");if(hddvd_object_name(object))printf(" name=%s",hddvd_object_name(object));putchar('\n');hddvd_object_free(object);return 0;}
static int dump_xmf(void*o,const char*n,const void*b,size_t z){return hddvd_xmf_dump(b,z,n,o);}
int main(int argc,char**argv){void*b=NULL;size_t n=0;int rc;if(argc!=2){fprintf(stderr,"Usage: %s archive.aca\n",argv[0]);return 2;}rc=hddvd_aca_list(argv[1],show_object,argv[1]);if(rc){fprintf(stderr,"Object inspection failed: %s\n",hddvd_strerror(rc));return 1;}rc=hddvd_aca_visit_xmf(argv[1],dump_xmf,stdout);if(rc){fprintf(stderr,"XMF inspection failed: %s\n",hddvd_strerror(rc));return 1;}rc=hddvd_aca_read_member(argv[1],"main.xmu",&b,&n);if(rc==HDDVD_OK){rc=hddvd_xmu_dump(b,n,"main.xmu",stdout);hddvd_free(b);}return rc==HDDVD_ENOTFOUND?0:(rc?1:0);}
